(** Minimal HTTP/1.1 message handling: one request per connection. *)

type request = {
  meth : string;
  path : string;
  headers : (string * string) list;  (** Names lower-cased. *)
  body : string;
}

type response = {
  status : int;
  headers : (string * string) list;
  body : string;
}

type read_error =
  | Closed  (** Peer closed before sending a complete request head. *)
  | Bad_request of string
  | Header_too_large
  | Payload_too_large
  | Not_implemented of string

val response : ?headers:(string * string) list -> ?body:string -> int -> response

val error_response : read_error -> response option
(** The response to send for a read error, if any. *)

val parse_head : string -> (string * string * (string * string) list, read_error) result
(** [parse_head head] parses the request line and header block (without the
    terminating blank line) into method, target and lower-cased headers. *)

val read_request :
  Unix.file_descr -> max_head:int -> max_body:int -> (request, read_error) result

val write_response : Unix.file_descr -> response -> unit

let max_head = 64 * 1024
let io_timeout = 30.0

let log fmt = Printf.eprintf (fmt ^^ "\n%!")

let close_quietly fd =
  try Unix.close fd with Unix.Unix_error _ -> ()

(* Half-close then drain briefly so the client sees the full response rather
   than a reset caused by unread request bytes. *)
let finish fd =
  (try Unix.shutdown fd Unix.SHUTDOWN_SEND with Unix.Unix_error _ -> ());
  close_quietly fd

let serve_connection store fd =
  Fun.protect
    ~finally:(fun () -> finish fd)
    (fun () ->
      try
        Unix.setsockopt_float fd Unix.SO_RCVTIMEO io_timeout;
        Unix.setsockopt_float fd Unix.SO_SNDTIMEO io_timeout;
        Unix.setsockopt fd Unix.TCP_NODELAY true;
        let reply =
          match
            Http.read_request fd ~max_head ~max_body:Router.max_value_size
          with
          | Ok req -> Some (Router.handle store req)
          | Error err -> Http.error_response err
        in
        Option.iter (Http.write_response fd) reply
      with Unix.Unix_error (e, fn, _) ->
        log "connection error: %s: %s" fn (Unix.error_message e))

let rec accept sock =
  match Unix.accept ~cloexec:true sock with
  | conn -> conn
  | exception Unix.Unix_error ((Unix.EINTR | Unix.ECONNABORTED), _, _) -> accept sock
  | exception Unix.Unix_error (((Unix.EMFILE | Unix.ENFILE) as e), _, _) ->
      log "accept: %s; backing off" (Unix.error_message e);
      Thread.delay 0.05;
      accept sock

let run ?(backlog = 512) addr port store =
  Sys.set_signal Sys.sigpipe Sys.Signal_ignore;
  let sock = Unix.socket ~cloexec:true Unix.PF_INET Unix.SOCK_STREAM 0 in
  Unix.setsockopt sock Unix.SO_REUSEADDR true;
  Unix.bind sock (Unix.ADDR_INET (addr, port));
  Unix.listen sock backlog;
  let rec loop () =
    let fd, _ = accept sock in
    ignore (Thread.create (serve_connection store) fd : Thread.t);
    loop ()
  in
  loop ()

type t = { lock : Mutex.t; table : (string, string) Hashtbl.t }

let create () = { lock = Mutex.create (); table = Hashtbl.create 1024 }
let with_lock t f = Mutex.protect t.lock f

let put t key value =
  with_lock t (fun () ->
      match Hashtbl.find_and_replace t.table key value with
      | None -> `Created
      | Some _ -> `Replaced)

let get t key = with_lock t (fun () -> Hashtbl.find_opt t.table key)

let delete t key =
  with_lock t (fun () -> Option.is_some (Hashtbl.find_and_remove t.table key))

let keys t =
  let ks = with_lock t (fun () -> Hashtbl.fold (fun k _ acc -> k :: acc) t.table []) in
  List.sort String.compare ks

open Kvhttp

let req ?(body = "") meth path : Http.request = { meth; path; headers = []; body }
let status store meth path ?body () = (Router.handle store (req ?body meth path)).status

let () =
  let s = Store.create () in
  assert (status s "GET" "/health" () = 200);
  assert (status s "POST" "/health" () = 405);
  assert (status s "GET" "/nope" () = 404);
  assert (status s "GET" "/kv/" () = 400);
  assert (status s "GET" "/kv/a/b" () = 400);
  assert (status s "GET" "/kv/bad.key" () = 400);
  assert (status s "GET" ("/kv/" ^ String.make 65 'a') () = 400);
  assert (status s "PUT" ("/kv/" ^ String.make 64 'a') ~body:"x" () = 201);
  assert (status s "PUT" "/kv/b" ~body:"1" () = 201);
  assert (status s "PUT" "/kv/b" ~body:"2" () = 200);
  assert (String.equal (Router.handle s (req "GET" "/kv/b")).body "2");
  assert (status s "PATCH" "/kv/b" () = 405);
  assert (status s "POST" "/kv" () = 405);
  assert (String.equal (Router.handle s (req "GET" "/kv")).body
            (Printf.sprintf "[%S,\"b\"]" (String.make 64 'a')));
  assert (status s "DELETE" "/kv/b" () = 204);
  assert (status s "DELETE" "/kv/b" () = 404);
  assert (status s "GET" "/kv/b" () = 404);
  (match Http.parse_head "GET /x HTTP/1.1\r\nHost: a\r\nContent-Length: 3" with
   | Ok ("GET", "/x", [ ("host", "a"); ("content-length", "3") ]) -> ()
   | Ok _ | Error _ -> assert false);
  assert (Result.is_error (Http.parse_head "GARBAGE"));
  print_endline "ok"
